def maxDistinctWindowSum(nums, k):
    cnt = {}
    distinct = 0
    cur = 0
    best = 0
    for i, x in enumerate(nums):
        c = cnt.get(x, 0)
        if c == 0:
            distinct += 1
        cnt[x] = c + 1
        cur += x
        if i >= k:
            y = nums[i - k]
            cnt[y] -= 1
            if cnt[y] == 0:
                distinct -= 1
            cur -= y
        if i >= k - 1 and distinct == k and cur > best:
            best = cur
    return best
